import { IGNORE_KEYS, THRESHOLD_KEYS } from "../limits.ts";

/** `key` in lower case without the quote mark, `-`, and `_`, so `fail_under` and `fail-under` are one key. */
export const normalizeKey = (key: string): string =>
  key
    .replace(/^["']|["']$/g, "")
    .replace(/[-_]/g, "")
    .toLowerCase();

/** True when `key` is a documented threshold key, where a lower number checks less. */
export const isThresholdKey = (key: string): boolean =>
  THRESHOLD_KEYS.has(normalizeKey(key));

/** True when `key` is a documented key of a list that switches off checks. */
export const isIgnoreKey = (key: string): boolean =>
  IGNORE_KEYS.has(normalizeKey(key));
